// test-setup.ts
import { server } from "./mocks/server";

beforeAll(() => server.listen());
afterAll(() => server.close());

let requests: string[] = [];   // shared request log

// flags.test.tsx
import { requests } from "../test-setup";

test("records the flags request", async () => {
  server.use(
    http.get("/api/flags", ({ request }) => {
      requests.push(request.url);
      return HttpResponse.json({ beta: true });
    })
  );
  render(<FeatureGate />);
  expect(await screen.findByText("Beta")).toBeInTheDocument();
  expect(requests).toContain("http://localhost/api/flags");
});
